import React, { createContext, useState, useEffect, useContext } from 'react';

interface User {
  email: string;
  nome: string;
  role: 'admin' | 'licenciado';
}

interface AuthContextType {
  user: User | null;
  login: (userData: User) => void;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const SESSION_DURATION_HOURS = 24;

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    const storedSession = localStorage.getItem('userSession');
    if (storedSession) {
      const sessionData = JSON.parse(storedSession);
      const now = new Date().getTime();

      // Verifica se a sessão expirou
      if (now > sessionData.expiry) {
        // Se expirou, limpa o localStorage
        localStorage.removeItem('userSession');
      } else {
        // Se não expirou, define o usuário
        setUser(sessionData.user);
      }
    }
  }, []);

  // Função de login atualizada
  const login = (userData: User) => {
    const now = new Date();
    // Define o prazo de validade (24 horas a partir de agora)
    const expiry = now.getTime() + (SESSION_DURATION_HOURS * 60 * 60 * 1000);

    const sessionData = {
      user: userData,
      expiry: expiry,
    };

    setUser(userData);
    // Salva o usuário e o prazo de validade no localStorage
    localStorage.setItem('userSession', JSON.stringify(sessionData));
  };

  // Função de logout atualizada
  const logout = () => {
    setUser(null);
    // Remove os dados do localStorage
    localStorage.removeItem('userSession');
  };

  return (
    <AuthContext.Provider value={{ user, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth deve ser usado dentro de AuthProvider');
  }
  return context;
};
